<?php
require_once 'config.php';
$q=trim($_GET['q']??'');$products=[];
if($q!==''){$like='%'.$q.'%';$stmt=$conn->prepare("SELECT p.id,p.name,p.price,p.image,p.stock,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.is_active=1 AND (p.name LIKE ? OR p.description LIKE ? OR c.name LIKE ?) ORDER BY p.created_at DESC");$stmt->bind_param('sss',$like,$like,$like);$stmt->execute();$r=$stmt->get_result();while($row=$r->fetch_assoc())$products[]=$row;$stmt->close();}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Search - Style Hub</title><link rel="stylesheet" href="style.css"></head><body><header><a class="logo" href="home.php">Style Hub</a><nav><a href="home.php">Home</a><a href="category.php?cat=Men">Men</a><a href="category.php?cat=Women">Women</a><a href="category.php?cat=Kids">Kids</a><a href="category.php?cat=Accessories">Accessories</a></nav><div class="header-right"><form class="search-box" action="search.php"><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search clothes..." autofocus></form><?php if(isset($_SESSION['user_id'])):?><a class="auth-btn" href="cart.php">Cart</a><?php endif;?></div></header><main class="section"><h2>Search Results<?= $q!==''?' for “'.htmlspecialchars($q).'”':'' ?></h2><?php if(!$q):?><div class="notice">Type a product, clothing name, or category in the search box.</div><?php elseif(!$products):?><div class="notice">No matching products found.</div><?php else:?><div class="product-grid search-results"><?php foreach($products as $p):?><article class="product-card"><img src="<?=htmlspecialchars($p['image'])?>" alt=""><div class="product-info"><span class="badge"><?=htmlspecialchars($p['category'])?></span><h3><?=htmlspecialchars($p['name'])?></h3><p class="price">₹<?=number_format($p['price'],2)?></p><button class="primary-btn add-cart" data-product="<?=$p['id']?>">Add to Cart</button></div></article><?php endforeach;?></div><?php endif;?></main><script src="script.js"></script></body></html>
